<script lang="ts">import{gameCommands,gameState}from'$lib/application/game-store';import{NPCS,QUESTS,FESTIVALS,type NpcId}from'$lib/content/village';export let close:()=>void;export let initialTab:'npc'|'quest'|'museum'|'calendar'='npc';let tab:'npc'|'quest'|'museum'|'calendar'=initialTab;const npcs=Object.entries(NPCS)as Array<[NpcId,(typeof NPCS)[NpcId]]>;const seasonDay=()=> (($gameState.day-1)%28)+1;</script>
<div class="modal" role="dialog" aria-modal="true"><section><button class="close" on:click={close}>×</button><nav><button on:click={()=>tab='npc'}>Warga</button><button on:click={()=>tab='quest'}>Quest</button><button on:click={()=>tab='museum'}>Museum</button><button on:click={()=>tab='calendar'}>Kalender</button></nav><h2>Desa · Reputasi {$gameState.village.reputation}</h2>
{#if tab==='npc'}<div class="cards">{#each npcs as [id,npc]}<article><b>{npc.name}</b><span>{npc.role} · ♥ {$gameState.village.relationships[id]??0}</span><small>{npc.schedule} · ulang tahun hari {npc.birthday}</small><button on:click={()=>gameCommands.talk(id)}>Bicara</button></article>{/each}</div>
{:else if tab==='quest'}<div class="cards quests">{#each QUESTS as q}<article><b>{q.name}</b><span>{q.category} · {q.quantity} {q.item}</span><small>{q.coins} koin · {q.reputation} reputasi</small>{#if $gameState.village.claimedQuests.includes(q.id)}<em>Selesai</em>{:else if $gameState.village.acceptedQuests.includes(q.id)}<button on:click={()=>gameCommands.claimQuest(q.id)}>Klaim</button>{:else}<button on:click={()=>gameCommands.acceptQuest(q.id)}>Terima</button>{/if}</article>{/each}</div>
{:else if tab==='museum'}<p>Donasikan ikan, serangga, mineral, artefak, atau tanaman langka. Setiap koleksi unik memberi 5 reputasi.</p><div class="cards">{#each Object.entries($gameState.inventory).filter(([id,q])=>q>0&&(id.startsWith('fish_')||['stone','copper','iron','gold','coal','crystal','rare_mineral','medicinal_plant','rare_herb'].includes(id))) as [id,qty]}<article><b>{id.replaceAll('_',' ')}</b><span>×{qty}</span><button disabled={$gameState.village.museum[id]} on:click={()=>gameCommands.donate(id)}>{$gameState.village.museum[id]?'Terdonasi':'Donasi'}</button></article>{/each}</div>
{:else}<p>Hari {seasonDay()} · {$gameState.season}. Kalender menampilkan festival dan ulang tahun warga.</p><div class="cards">{#each FESTIVALS as f}<article><b>{f.name}</b><span>{f.season} · hari {f.day}</span><button on:click={()=>gameCommands.festival(f.id)}>Ikuti</button></article>{/each}{#each npcs as [,npc]}<article><b>Ulang Tahun {npc.name}</b><span>Hari {npc.birthday}</span></article>{/each}</div>{/if}</section></div>
<style>.modal{position:fixed;z-index:20;inset:0;background:#071a16dd;display:grid;place-items:center;padding:15px}section{position:relative;width:min(850px,100%);max-height:92vh;overflow:auto;padding:25px;background:#e8ddb8;color:#203c35;border:8px double #6e5037}.close{position:absolute;right:8px;top:6px;border:0;background:none;font-size:1.6rem}nav{display:flex;gap:5px}nav button,.cards button{padding:8px;background:#315d4b;color:white;border:0}h2{font:900 2rem Georgia}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.cards article{display:grid;gap:5px;padding:10px;background:#fff7d9;border:2px solid #927340}.cards span,.cards small{font-size:.68rem}.cards em{color:#3c7b51}.quests{grid-template-columns:repeat(2,1fr)}@media(max-width:600px){.cards,.quests{grid-template-columns:1fr 1fr}}</style>
